using System;
using System.IO;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
namespace IUHCampus.Guardian.Progress.Tests
{
 public class ProgressTests
 {
  GuardianItemDefinition item; GuardianItemDatabase db; GuardianProgressState state;
  [SetUp] public void Setup(){item=ScriptableObject.CreateInstance<GuardianItemDefinition>();item.id="seed";item.maxStack=3;item.stackable=true;db=ScriptableObject.CreateInstance<GuardianItemDatabase>();db.definitions.Add(item);state=new GuardianProgressState();}
  [TearDown] public void Cleanup(){UnityEngine.Object.DestroyImmediate(db);UnityEngine.Object.DestroyImmediate(item);}
  [Test] public void InventoryLimits(){var inv=new GuardianInventory(state,db);Assert.IsTrue(inv.Add("seed",3));Assert.IsFalse(inv.Add("seed",1));Assert.IsFalse(inv.Remove("seed",4));Assert.IsTrue(inv.Remove("seed",3));Assert.AreEqual(0,inv.Count("seed"));Assert.IsFalse(inv.Add("seed",-1));}
  [Test] public void SharedRewardLedger(){var inv=new GuardianInventory(state,db);var wallet=new GuardianWallet(state);Assert.IsTrue(wallet.AddCore(10,"r"));Assert.IsFalse(inv.Add("seed",1,"r"));Assert.IsFalse(wallet.AddCore(10,"r"));Assert.IsTrue(inv.Add("seed",1,"s"));Assert.IsFalse(wallet.AddCore(1,"s"));Assert.IsFalse(wallet.SpendCore(11,"shop"));Assert.IsTrue(wallet.SpendCore(10,"shop"));Assert.IsFalse(wallet.AddCore(-1,"bad"));}
  [Test] public void UnknownIdWarnsOnce(){var inv=new GuardianInventory(state,db);LogAssert.Expect(LogType.Warning,"[IUH Guardian] Unknown item id: missing");Assert.IsFalse(inv.Add("missing",1));Assert.IsFalse(inv.Add("missing",1));}
  [Test] public void DuplicateDatabaseRejected(){db.definitions.Add(item);Assert.Throws<ArgumentException>(()=>db.Validate());}
  [Test] public void SaveReloadAndRecovery(){var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());try{var store=new GuardianProgressStore(dir);state.campusCore=10;store.Save(state);state.campusCore=20;store.Save(state);Assert.AreEqual(20,new GuardianProgressStore(dir).Load(()=>new GuardianProgressState()).campusCore);File.WriteAllText(store.Path,"broken");LogAssert.Expect(LogType.Warning,"[IUH Guardian] Progress recovered from backup.");Assert.AreEqual(10,store.Load(()=>new GuardianProgressState()).campusCore);File.WriteAllText(store.Path+".bak","broken");LogAssert.Expect(LogType.Warning,"[IUH Guardian] Progress files invalid; starting new progress.");Assert.AreEqual(0,new GuardianProgressStore(dir).Load(()=>new GuardianProgressState()).campusCore);}finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}}
  [Test] public void StarterUsesConfigOnce(){var cfg=ScriptableObject.CreateInstance<GuardianProgressConfig>();try{cfg.startingItems.Clear();cfg.randomSeedIds=new[]{"seed"};cfg.startingRandomSeeds=2;var s=GuardianProgressFactory.Create(cfg,db,new System.Random(1));Assert.AreEqual(2,new GuardianInventory(s,db).Count("seed"));Assert.Contains(GuardianProgressFactory.StarterReward,s.appliedRewardIds);Assert.AreEqual(cfg.plotCount,s.gardenPlots.Count);}finally{UnityEngine.Object.DestroyImmediate(cfg);}}
  [Test] public void FailedGrantDoesNotConsumeReward(){var inv=new GuardianInventory(state,db);Assert.IsFalse(inv.Add("seed",4,"retry"));Assert.IsTrue(inv.Add("seed",2,"retry"));var snapshot=inv.Items;inv.Remove("seed",1);Assert.AreEqual(2,snapshot["seed"]);}
  [Test] public void PersistedRewardsAndStarterAreNotGrantedAgain(){var cfg=ScriptableObject.CreateInstance<GuardianProgressConfig>();var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());try{cfg.startingItems.Clear();cfg.randomSeedIds=new[]{"seed"};cfg.startingRandomSeeds=3;cfg.plotCount=9;var store=new GuardianProgressStore(dir);var created=GuardianProgressFactory.Create(cfg,db,new System.Random(4));new GuardianWallet(created).AddCore(7,"win");store.Save(created);var loaded=new GuardianProgressStore(dir).Load(()=>{Assert.Fail("Must not grant starter again");return null;});Assert.AreEqual(9,loaded.gardenPlots.Count);Assert.AreEqual(3,new GuardianInventory(loaded,db).Count("seed"));Assert.IsFalse(new GuardianWallet(loaded).AddCore(7,"win"));Assert.AreEqual(7,loaded.campusCore);}finally{UnityEngine.Object.DestroyImmediate(cfg);if(Directory.Exists(dir))Directory.Delete(dir,true);}}
  [Test] public void ShippedAssetsValid(){var database=UnityEditor.AssetDatabase.LoadAssetAtPath<GuardianItemDatabase>("Assets/IUH_Campus/Data/Guardian/Progress/GuardianItemDatabase.asset");Assert.NotNull(database);database.Validate();Assert.AreEqual(5,database.definitions.Count);var cfg=UnityEditor.AssetDatabase.LoadAssetAtPath<GuardianProgressConfig>("Assets/IUH_Campus/Data/Guardian/Progress/GuardianProgressConfig.asset");var created=GuardianProgressFactory.Create(cfg,database);var inv=new GuardianInventory(created,database);Assert.AreEqual(1,inv.Count("tool_watering_can"));Assert.IsFalse(inv.Add("tool_watering_can",1));int total=0;foreach(var stack in created.inventory)total+=stack.qty;Assert.AreEqual(3,total);}

 }
}
